function formatPrice(cents) {
  return "$" + cents / 100;
}

function discountPrice(cents, percent) {
  return cents * percent / 100;
}
module.exports = { formatPrice, discountPrice };

function add(a, b) {
  return a + b;
}

/**
 * Returns n constrained to the inclusive range [min, max].
 * @param {number} n - value to clamp
 * @param {number} min - lower bound
 * @param {number} max - upper bound
 * @returns {number} min if n < min, max if n > max, otherwise n
 */
function clamp(n, min, max) {
  return Math.min(max, Math.max(min, n));
}

module.exports = { add, clamp };
